'use strict';
const C=Coral, KEY='coral-salidas-v1', $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={version:1,trips:[]},activeId='',view='overview',floorIndex=0,tool='add',moving='',query='',reportType='passengers',reportFilter='',storageBlocked=false;
let cloudBase=CoralCloud.snapshot(),saving=false,remotePending=false;data=structuredClone(cloudBase.data);
activeId=data.trips[0]?.id||'';
const trip=()=>data.trips.find(t=>t.id===activeId);
const group=(t,id)=>t.groups.find(g=>g.id===id);
const seatLabel=(t,id)=>C.seats(t).find(s=>s.id===id)?.label||'—';
const fullName=p=>`${p.firstName} ${p.lastName}`;
const dateText=s=>s?s.split('-').reverse().join('/'):'Sin definir';
const groupColor=(t,p)=>group(t,p.groupId)?.color||'#337b58';
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
async function persist(){
 if(saving)return false;saving=true;
 try{cloudBase=await CoralCloud.save(data,cloudBase);data=structuredClone(cloudBase.data);remotePending=false;$('#save-status').textContent='Guardado en Firebase';notify('Cambios guardados en Firebase.');return true;}
 catch(e){cloudBase=CoralCloud.snapshot();data=structuredClone(cloudBase.data);notify(e.message);$('#save-status').textContent='El cambio no se guardó';return false;}
 finally{saving=false;render();}
}
async function mutate(fn){if(saving)return;if(remotePending){notify('Llegaron cambios de otro equipo. Cerrá el formulario y revisá la versión actual antes de guardar.');return;}const previous=structuredClone(data);try{fn();await persist();render();}catch(e){data=previous;notify(e.message);}}
function button(text,action,cls='secondary',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,options,value=''){return `<label class="field">${label}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function pageTitle(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`;}
function modal(title,content){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('✕','close','text-button','aria-label="Cerrar"')}</div>${content}`;$('#modal').showModal();}
function closeModal(){$('#modal').close();if(remotePending&&!saving){cloudBase=CoralCloud.snapshot();data=structuredClone(cloudBase.data);remotePending=false;render();}}
function confirmAction(title,message,callback){modal(title,`<p>${esc(message)}</p><div class="modal-actions">${button('Cancelar','close')}${button('Confirmar','confirm','danger')}</div>`);$('#modal [data-action=confirm]').onclick=()=>{closeModal();callback();};}
function render(){const t=trip();const items=[['overview','◫','Resumen'],['bus','▦','Colectivo'],['passengers','♙','Pasajeros'],['boarding','✓','Tomar lista'],['groups','◉','Grupos'],['rooming','▤','Rooming'],['documents','▧','Documentos']];$('#nav').innerHTML=items.map(([id,icon,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${(!t||(id!=='bus'&&id!=='overview'&&id!=='boarding'&&!t.configured))?'disabled':''}><b>${icon}</b>${label}</button>`).join('');$('#breadcrumb').textContent=items.find(x=>x[0]===view)?.[2]||'Salidas';$('#trip-select').innerHTML=data.trips.length?data.trips.map(s=>`<option value="${esc(s.id)}" ${s.id===activeId?'selected':''}>${esc(s.name)}</option>`).join(''):'<option>Sin salidas</option>';if(!t){renderWelcome();return;}if(floorIndex>=t.floors.length)floorIndex=0;({overview:renderOverview,bus:renderBus,passengers:renderPassengers,groups:renderGroups,rooming:renderRooming,documents:renderDocuments}[view]||renderOverview)(t);}
function renderWelcome(){$('#main').innerHTML=pageTitle('OPERACIONES','Cada viaje, en un solo lugar','Configurá el colectivo y después comenzá a cargar pasajeros.')+`<div class="two-col"><section class="card"><span class="chip green">PRIMERA SALIDA</span><h2 style="margin:24px 0 12px">Armemos tu próximo viaje</h2><p class="muted">Elegí una plantilla de 42 o 58 butacas, o una capacidad personalizada. Podés cambiar pisos, posiciones y números antes de confirmar el plano.</p>${button('+ Crear una salida','new','primary')}<div class="section-title"></div><div class="summary-row"><span>01 · Configurar</span><strong>Viaje y colectivo</strong></div><div class="summary-row"><span>02 · Organizar</span><strong>Pasajeros y grupos</strong></div><div class="summary-row"><span>03 · Preparar</span><strong>Rooming y documentos</strong></div></section><section class="card"><h2>Un mismo registro para todo</h2><p class="muted">Los cambios de un pasajero se reflejan en la taquilla, la lista de pasajeros, los roomings, los vouchers y el manifiesto.</p><div class="notice">Tus salidas se guardan en Firebase y se sincronizan con el iPad. También podés descargar un respaldo independiente.</div><div class="actions">${button('Restaurar respaldo','restore')}${button('Probar con datos ficticios','demo')}</div></section></div>`;}
function newTrip(){modal('Nueva salida',`<form id="new-form"><div class="form-grid">${field('Nombre de la salida','name','','text','required placeholder="Ej. Florianópolis · Enero 2027" maxlength="100"')}${field('Fecha de salida','departure','','date')}${field('Origen','origin','Córdoba')}${field('Destino','destination','Florianópolis')}${selectField('Plantilla de colectivo','capacity',[['42','42 butacas'],['58','58 butacas'],['custom','Personalizada']],'42')}${field('Cantidad personalizada','customCount',42,'number','min="1" max="100"')}${selectField('Pisos','floors',[['single','Un piso'],['double','Dos pisos']])}${selectField('Distribución por fila','arrangement',[['2-2','2 + pasillo + 2'],['2-1','2 + pasillo + 1'],['1-2','1 + pasillo + 2']])}</div><p class="muted">Las plantillas son un punto de partida: ajustá el plano a tu unidad en el siguiente paso.</p><div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Crear y configurar colectivo</button></div></form>`);$('#new-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));mutate(()=>{const t=C.blankTrip();Object.assign(t,{name:f.name.trim()||'Nueva salida',departure:f.departure,origin:f.origin,destination:f.destination,floors:C.layout(Number(f.capacity==='custom'?f.customCount:f.capacity),f.floors,f.arrangement)});data.trips.push(t);activeId=t.id;floorIndex=0;view='bus';closeModal();});};}
function stats(t){const all=C.seats(t).length,occupied=t.passengers.filter(p=>p.seatId).length;return `<div class="stats">${[['Butacas ocupadas',`${occupied} / ${all}`,`${all-occupied} disponibles`],['Pasajeros',t.passengers.length,`${t.passengers.filter(p=>p.noSeat).length} sin butaca`],['Grupos',t.groups.length,`${new Set(t.passengers.map(p=>p.hotel).filter(Boolean)).size} alojamientos`],['Embarcados',t.passengers.filter(p=>p.boarded).length,`${t.passengers.length} personas en la lista`]].map(([label,n,caption],i)=>`<div class="card stat ${i===0?'accent':''}"><span class="stat-label">${label}</span><strong>${n}</strong><small>${caption}</small></div>`).join('')}</div>`;}
function renderOverview(t){const missing=t.passengers.filter(p=>!p.noSeat&&!p.seatId).length;$('#main').innerHTML=pageTitle('SALIDA ACTIVA',t.name,`${t.origin} → ${t.destination} · ${dateText(t.departure)}`,button('Editar viaje','trip-edit')+button(t.configured?'+ Pasajero':'Configurar colectivo',t.configured?'passenger-new':'goto-bus','primary'))+stats(t)+(!t.configured?`<div class="notice warning">Primero revisá y confirmá el plano del colectivo para habilitar la carga de pasajeros.</div>`:'')+`<div class="two-col"><section class="card"><div class="card-header"><h2>El viaje</h2><span class="chip">${t.configured?'En preparación':'Configuración inicial'}</span></div>${[['Salida',dateText(t.departure)],['Regreso',dateText(t.returnDate)],['Presentación',t.presentation||'Sin definir'],['Horario de salida',t.departureTime||'Sin definir'],['Embarque',t.boardingPlace||'Sin definir'],['Check in / out',`${dateText(t.checkIn)} · ${dateText(t.checkOut)}`],['Coordinación',t.coordinator||'Sin definir'],['Transporte',t.carrier||'Sin definir']].map(([l,v])=>`<div class="summary-row"><span class="muted">${l}</span><strong>${esc(v)}</strong></div>`).join('')}</section><section class="card"><h2>Preparación de la salida</h2><div class="progress"><span style="width:${t.passengers.length?Math.round(t.passengers.filter(p=>p.boarded).length/t.passengers.length*100):0}%"></span></div><small>Avance del embarque</small>${[['Por asignar butaca',missing],['Sin documento',t.passengers.filter(p=>!p.document).length],['Sin alojamiento',t.passengers.filter(p=>!p.hotel&&p.role==='Pasajero').length],['Sin fecha de nacimiento',t.passengers.filter(p=>!p.birthDate).length]].map(([l,n])=>`<div class="summary-row"><span>${l}</span><span class="chip ${n?'':'green'}">${n}</span></div>`).join('')}<div class="notice">La edad se calcula a la fecha de salida. El embarque puede marcarse por persona o para todo su grupo.</div><div class="actions">${button('Descargar respaldo','backup')}${button('Restaurar','restore')}</div></section></div><section class="card" style="margin-top:24px"><div class="card-header"><h2>Mis salidas</h2>${button('+ Nueva salida','new')}</div><div class="trip-list">${data.trips.map(s=>`<div class="trip-entry"><div><strong>${esc(s.name)}</strong><small style="display:block;margin-top:5px">${dateText(s.departure)} · ${s.passengers.length} pasajeros</small></div><div class="actions">${button('Abrir','open-trip','secondary',`data-id="${esc(s.id)}"`)}${button('Reutilizar plano','clone-trip','secondary',`data-id="${esc(s.id)}"`)}</div></div>`).join('')}</div></section>`;}
const fixtureIcons={
  bathroom:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h6v8H5zM6 11h13v2a6 6 0 0 1-6 6H9a3 3 0 0 1-3-3zM10 19v3h7M15 5v4"/></svg>',
  stairs:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 20h5v-5h5v-5h5V5h4M3 13 15 1M4 5V2h3"/></svg>',
  coffee:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9h12v7a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM16 10h2a3 3 0 0 1 0 6h-2M3 23h16M7 2v3M12 2v3"/></svg>'
};
function editorToolbar(){
  const help={rename:'Tocá una butaca para cambiar su número o etiqueta.',move:moving?'Elegí un espacio vacío de este piso o de otro para mover el elemento.':'Tocá una butaca o un equipamiento; después elegí su nueva posición.',add:'Tocá un espacio vacío para agregar una butaca.',bathroom:'Tocá un espacio vacío para colocar un baño.',stairs:'Tocá un espacio vacío para colocar una escalera.',coffee:'Tocá un espacio vacío para colocar una cafetera.',remove:'Tocá una butaca libre o un equipamiento para quitarlo.'};
  return `<div class="editor-toolbar"><div class="tools" role="group" aria-label="Herramientas del plano">${[['add','+ Butaca'],['bathroom','Baño'],['stairs','Escalera'],['coffee','Cafetera'],['rename','Renumerar'],['move','Mover'],['remove','Quitar']].map(([id,label])=>button((fixtureIcons[id]||'')+label,'tool',tool===id?'active':'secondary',`data-tool="${id}" aria-pressed="${tool===id}"`)).join('')}</div><p class="editor-help" role="status">${help[tool]}</p></div>`;
}
function busMarkup(t,editing=false){
  const f=t.floors[floorIndex];
  return `<div class="floor-tabs">${t.floors.map((f,i)=>button(esc(f.name),'floor',i===floorIndex?'active':'secondary',`data-index="${i}"`)).join('')}</div>${editing?editorToolbar():''}<div class="bus"><div class="bus-front"><span>FRENTE DEL COLECTIVO</span><span>◉</span></div><div class="seat-grid" style="grid-template-columns:repeat(${f.cols},1fr)">${Array.from({length:f.rows*f.cols},(_,i)=>{
    const row=Math.floor(i/f.cols),col=i%f.cols,s=f.seats.find(s=>s.row===row&&s.col===col),item=(f.fixtures||[]).find(x=>x.row===row&&x.col===col),p=s&&t.passengers.find(p=>p.seatId===s.id);
    if(item)return `<button type="button" class="fixture ${moving===item.id?'selected':''}" data-action="fixture" data-id="${esc(item.id)}" aria-label="${C.fixtureTypes[item.type]}, fila ${row+1}, columna ${col+1}" title="${C.fixtureTypes[item.type]}" ${editing?'':'aria-disabled="true"'}>${fixtureIcons[item.type]}<span>${C.fixtureTypes[item.type]}</span></button>`;
    return s?`<button type="button" class="seat ${p?'occupied':''} ${p?.boarded?'boarded':''} ${moving===s.id?'selected':''}" style="--group-color:${p?groupColor(t,p):'#337b58'}" data-action="seat" data-id="${esc(s.id)}" title="Butaca ${esc(s.label)}${p?' · '+esc(fullName(p)):''}" aria-label="Butaca ${esc(s.label)}, ${p?esc(fullName(p)):'libre'}">${esc(s.label)}</button>`:`<button type="button" class="space ${editing?'editable':''}" data-action="space" data-row="${row}" data-col="${col}" ${editing?'':'disabled'} aria-label="Espacio vacío, fila ${row+1}, columna ${col+1}">${editing?'+':''}</button>`;
  }).join('')}</div></div><div class="legend"><span><i></i>Disponible</span><span><i class="filled"></i>Asignada</span><span>✓ Embarcado</span>${(f.fixtures||[]).length?'<span>Equipamiento en gris</span>':''}</div>`;
}
function renderBus(t){$('#main').innerHTML=pageTitle('COLECTIVO',t.configured?'Mapa de butacas':'Diseñá tu colectivo',t.configured?'Seleccioná una butaca para ver o asignar un pasajero.':'Ajustá la distribución y numeración antes de cargar pasajeros.',t.configured?button('Editar plano','unlock-layout'):button('Confirmar plano','confirm-layout','primary'))+`<div class="two-col config-layout"><section class="card"><div class="card-header"><h2>${t.configured?'Ocupación':'Configuración del plano'}</h2><span class="chip green">${C.seats(t).length} butacas</span></div>${t.configured?`<div class="summary-row"><span>Ocupadas</span><strong>${t.passengers.filter(p=>p.seatId).length}</strong></div><div class="summary-row"><span>Disponibles</span><strong>${C.seats(t).length-t.passengers.filter(p=>p.seatId).length}</strong></div><div class="summary-row"><span>Pasajeros sin asignar</span><strong>${t.passengers.filter(p=>!p.noSeat&&!p.seatId).length}</strong></div><div class="notice">Cada grupo tiene su color. Podés cambiar de butaca desde la ficha del pasajero.</div>${button('+ Cargar pasajero','passenger-new','primary')}`:`<form id="layout-form"><div class="form-grid">${field('Cantidad total','count',C.seats(t).length,'number','min="1" max="100" required')}${selectField('Pisos','floors',[['single','Un piso'],['double','Dos pisos']],t.floors.length===2?'double':'single')}${selectField('Distribución','arrangement',[['2-2','2 + pasillo + 2'],['2-1','2 + pasillo + 1'],['1-2','1 + pasillo + 2']])}</div><button class="secondary" type="submit" style="margin-top:18px" ${t.passengers.some(p=>p.seatId)?'disabled':''}>Regenerar plano</button></form><p class="muted" style="font-size:13px">Regenerar reemplaza el plano. No está disponible mientras haya butacas asignadas.</p><h3 class="section-title">Dimensiones del piso</h3><div class="actions">${button('+ Fila','add-row')}${button('− Fila vacía','remove-row')}${button('Nombre del piso','floor-name')}</div><div class="notice">Elegí una herramienta sobre el plano y tocá una celda. Baño, escalera y cafetera ocupan un espacio, pero no cuentan como butacas.</div>`}<div id="seat-detail" class="selection-detail"><h3>Datos del viaje</h3><p class="muted">${esc(t.origin)} → ${esc(t.destination)}<br>${dateText(t.departure)}</p>${button('Editar datos del viaje','trip-edit')}</div></section><section class="card"><div class="card-header"><h2>${t.configured?'Taquilla':'Vista del colectivo'}</h2><span class="chip">${t.floors.length} ${t.floors.length===1?'piso':'pisos'}</span></div>${busMarkup(t,!t.configured)}</section></div>`;if($('#layout-form'))$('#layout-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));confirmAction('Regenerar plano','Se reemplazarán la distribución, la numeración y el equipamiento del plano. Los pasajeros sin butaca se conservarán.',()=>mutate(()=>{if(t.passengers.some(p=>p.seatId))throw Error('Liberá las butacas antes de regenerar.');t.floors=C.layout(Number(f.count),f.floors,f.arrangement);floorIndex=0;moving='';}));};}
function promptValue(title,label,value,callback){modal(title,`<form id="value-form">${field(label,'value',value,'text','required maxlength="50"')}<div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Guardar</button></div></form>`);$('#value-form').onsubmit=e=>{e.preventDefault();mutate(()=>{callback(new FormData(e.target).get('value').trim());closeModal();});};}
function handleSeat(id){const t=trip(),s=C.seats(t).find(s=>s.id===id),p=t.passengers.find(p=>p.seatId===id);if(t.configured){$('#seat-detail').innerHTML=p?`<span class="eyebrow">BUTACA ${esc(s.label)}</span><h3 style="margin-top:12px">${esc(fullName(p))}</h3><p class="muted">${esc(group(t,p.groupId)?.name||'Sin grupo')}<br>${esc(p.boarding||'Embarque sin definir')}</p><div class="actions">${button('Editar pasajero','passenger-edit','primary',`data-id="${esc(p.id)}"`)}${button(p.boarded?'Desmarcar embarque':'Marcar embarque','board','secondary',`data-id="${esc(p.id)}"`)}</div>`:`<h3>Butaca ${esc(s.label)} · Disponible</h3><div class="actions">${button('Nuevo pasajero','passenger-seat','primary',`data-id="${esc(s.id)}"`)}${button('Asignar pasajero existente','assign-seat','secondary',`data-id="${esc(s.id)}"`)}</div>`;return;}if(tool==='rename'){promptValue('Renumerar butaca','Número o etiqueta',s.label,label=>{if(!label||C.seats(t).some(q=>q.id!==s.id&&C.norm(q.label)===C.norm(label)))throw Error('La etiqueta debe ser única y no estar vacía.');s.label=label;});}else if(tool==='move'){moving=id;render();notify('Ahora seleccioná un espacio vacío.');}else if(tool==='remove'){if(p){notify('No se puede quitar una butaca ocupada.');return;}mutate(()=>C.removeItem(t,id));}}
function handleFixture(id){
  const t=trip();if(t.configured)return;
  if(tool==='move'){moving=id;render();}
  else if(tool==='remove')mutate(()=>C.removeItem(t,id));
  else notify('Para cambiar de lugar este elemento, elegí Mover. Para eliminarlo, elegí Quitar.');
}
function handleSpace(row,col){
  const t=trip(),f=t.floors[floorIndex];if(t.configured)return;
  if(tool==='move'&&moving)mutate(()=>{C.placeItem(t,f.id,row,col,'seat',moving);moving='';});
  else if(tool==='add'||C.fixtureTypes[tool])mutate(()=>C.placeItem(t,f.id,row,col,tool==='add'?'seat':tool));
  else notify(tool==='move'?'Primero seleccioná el elemento que querés mover.':'Elegí Butaca, Baño, Escalera o Cafetera para colocar un elemento.');
}
function editTrip(){const t=trip();const fields=[['Nombre de la salida','name'],['Origen','origin'],['Destino','destination'],['Salida','departure','date'],['Regreso','returnDate','date'],['Check in','checkIn','date'],['Check out','checkOut','date'],['Presentación','presentation'],['Horario de salida','departureTime'],['Lugar de embarque','boardingPlace'],['Coordinador y teléfono','coordinator'],['Empresa transportista','carrier'],['Unidad','vehicle'],['Dominio / patente','plate'],['Ruta','route'],['Paso fronterizo','border'],['Proveedor / agencia emisora','provider']];modal('Datos de la salida',`<form id="trip-form"><div class="form-grid">${fields.map(([l,k,type])=>field(l,k,t[k],type||'text',k==='name'?'required':'')).join('')}</div><div class="modal-actions">${button('Cancelar','close')}<button class="primary" type="submit">Guardar datos</button></div></form>`);$('#trip-form').onsubmit=e=>{e.preventDefault();mutate(()=>{const draft={...t,...Object.fromEntries(new FormData(e.target))};C.validateTrip(draft);Object.assign(t,draft);closeModal();});};}
function passengerTable(t,list,actions=true){return `<div class="table-wrap"><table><thead><tr><th>Pasajero</th><th>Grupo</th><th>Butaca</th><th>Hospedaje</th><th>Embarque</th>${actions?'<th></th>':''}</tr></thead><tbody>${list.map(p=>`<tr><td><span class="person-name">${esc(fullName(p))}</span><small>${esc(p.documentType)} ${esc(p.document||'sin documento')} · ${C.age(p.birthDate,t.departure)===''?'Edad pendiente':C.age(p.birthDate,t.departure)+' años'}</small></td><td><span class="group-dot" style="background:${groupColor(t,p)}"></span>${esc(group(t,p.groupId)?.name||'Sin grupo')}</td><td><span class="chip">${p.noSeat?'Sin butaca':esc(seatLabel(t,p.seatId))}</span></td><td>${esc(p.hotel||'Sin asignar')}<small>${esc(p.roomType)}</small></td><td>${actions?button(p.boarded?'✓ Embarcado':'Pendiente','board',p.boarded?'primary':'secondary',`data-id="${esc(p.id)}"`):p.boarded?'Sí':'No'}<small>${esc(p.boarding)}</small></td>${actions?`<td>${button('Editar','passenger-edit','secondary',`data-id="${esc(p.id)}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function renderPassengers(t){const list=t.passengers.filter(p=>C.norm([fullName(p),p.document,group(t,p.groupId)?.name,p.hotel,p.boarding].join(' ')).includes(C.norm(query)));$('#main').innerHTML=pageTitle('LISTA MAESTRA','Pasajeros','Una ficha por persona, compartida por todos los documentos.',button('+ Cargar pasajero','passenger-new','primary'))+stats(t)+`<section class="card"><div class="toolbar"><label class="sr-only" for="search">Buscar pasajeros</label><input id="search" placeholder="Buscar nombre, documento o grupo…" value="${esc(query)}"><span class="chip">${list.length} personas</span><div style="margin-left:auto">${button('Exportar CSV','csv')}</div></div>${list.length?passengerTable(t,list):`<div class="empty"><h3>${query?'No hay coincidencias':'Todavía no hay pasajeros'}</h3><p>${query?'Probá otra búsqueda.':'Cargá el primer pasajero y asignale una butaca.'}</p>${query?'':button('+ Cargar pasajero','passenger-new','primary')}</div>`}</section>`;$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;renderPassengers(t);$('#search').focus();$('#search').setSelectionRange(pos,pos);};}
function editPassenger(id='',seat=''){const t=trip();if(!t.configured){notify('Confirmá el plano antes de cargar pasajeros.');return;}const p=id?{...t.passengers.find(p=>p.id===id)}:{...C.blankPassenger(),seatId:seat,origin:t.origin,destination:t.destination,boarding:t.boardingPlace};const available=C.seats(t).filter(s=>!t.passengers.some(q=>q.id!==p.id&&q.seatId===s.id));modal(id?'Editar pasajero':'Nuevo pasajero',`<form id="passenger-form"><div class="form-grid">${field('Nombre','firstName',p.firstName,'text','required maxlength="100"')}${field('Apellido','lastName',p.lastName,'text','required maxlength="100"')}${selectField('Tipo de documento','documentType',['DNI','Pasaporte','Cédula','Otro'],p.documentType)}${field('Número de documento','document',p.document)}${field('Nacimiento','birthDate',p.birthDate,'date')}${selectField('Sexo (documento)','sex',[['','Sin informar'],'F','M','X'],p.sex)}${field('Nacionalidad','nationality',p.nationality)}${field('País de residencia','residence',p.residence)}${field('Ocupación','occupation',p.occupation)}${field('Teléfono','phone',p.phone,'tel')}${selectField('Grupo','groupId',[['','Sin grupo'],...t.groups.map(g=>[g.id,g.name]),['__new','+ Crear grupo']],p.groupId)}${selectField('Butaca','seatId',[['','Por asignar'],...available.map(s=>[s.id,s.label])],p.seatId)}<label class="check"><input type="checkbox" name="noSeat" ${p.noSeat?'checked':''}>No ocupa butaca</label>${selectField('Tipo de viajero','role',['Pasajero','Coordinador','Tripulante'],p.role)}${field('Origen','origin',p.origin)}${field('Destino','destination',p.destination)}${field('Punto de embarque','boarding',p.boarding)}${field('Hospedaje','hotel',p.hotel,'text','list="hotels-list"')}${field('Tipo de habitación','roomType',p.roomType)}${field('Número de habitación','room',p.room)}${field('Camas / distribución','beds',p.beds)}${field('Régimen','meal',p.meal,'text','placeholder="Ej. Desayuno"')}<label class="field span2">Observaciones<textarea name="notes" rows="2">${esc(p.notes)}</textarea></label><label class="check span2"><input type="checkbox" name="applyGroup">Aplicar hospedaje, habitación y régimen a todo el grupo</label></div><datalist id="hotels-list">${[...new Set(t.passengers.map(p=>p.hotel).filter(Boolean))].map(h=>`<option value="${esc(h)}">`).join('')}</datalist><div id="new-group-field" hidden style="margin-top:15px">${field('Nombre del nuevo grupo','newGroupName','','text','placeholder="Ej. Familia Fernández"')}</div><div class="modal-actions">${id?button('Eliminar pasajero','passenger-delete','danger',`data-id="${esc(id)}" style="margin-right:auto"`):''}${button('Cancelar','close')}<button class="primary" type="submit">Guardar pasajero</button></div></form>`);const form=$('#passenger-form');form.elements.groupId.onchange=()=>{$('#new-group-field').hidden=form.elements.groupId.value!=='__new';};const syncNoSeat=()=>{form.elements.seatId.disabled=form.elements.noSeat.checked;if(form.elements.noSeat.checked)form.elements.seatId.value='';};form.elements.noSeat.onchange=syncNoSeat;syncNoSeat();form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));mutate(()=>{const draft={...p};for(const k of Object.keys(p))if(k in f&&typeof p[k]==='string'&&k!=='id')draft[k]=String(f[k]).trim();draft.noSeat=!!f.noSeat;draft.seatId=draft.noSeat?'':f.seatId||'';let ng;if(f.groupId==='__new'){if(!f.newGroupName.trim())throw Error('Escribí el nombre del nuevo grupo.');if(t.groups.some(g=>C.norm(g.name)===C.norm(f.newGroupName)))throw Error('Ya existe un grupo con ese nombre.');ng={id:C.uid(),name:f.newGroupName.trim(),color:palette[t.groups.length%palette.length]};draft.groupId=ng.id;}const candidate={...t,groups:ng?[...t.groups,ng]:t.groups};C.validatePassenger(candidate,draft);if(ng)t.groups.push(ng);C.savePassenger(t,draft);if(f.applyGroup&&draft.groupId)t.passengers.forEach(q=>{if(q.groupId===draft.groupId)for(const k of ['hotel','roomType','room','beds','meal'])q[k]=draft[k];});closeModal();});};}
const palette=['#337b58','#4964a5','#945b9c','#b15d34','#487747','#936e24','#297b9b','#a64962'];
function renderGroups(t){$('#main').innerHTML=pageTitle('RESERVAS','Grupos','Agrupá personas, identificá sus butacas y controlá el embarque.',button('+ Nuevo grupo','group-new','primary'))+(t.groups.length?t.groups.map(g=>{const people=t.passengers.filter(p=>p.groupId===g.id);return `<section class="card group-card" style="--group-color:${g.color}"><div class="card-header"><div><h2>${esc(g.name)}</h2><small>${people.length} personas · ${people.filter(p=>p.boarded).length} embarcadas</small></div><div class="actions">${button('Editar grupo','group-edit','secondary',`data-id="${esc(g.id)}"`)}${button('Marcar todo el grupo','group-board','primary',`data-id="${esc(g.id)}"`)}</div></div>${people.length?passengerTable(t,people):'<p class="muted">Asigná pasajeros a este grupo desde sus fichas.</p>'}</section>`;}).join(''):`<section class="card empty"><h3>Creá tu primer grupo</h3><p>Usá un nombre reconocible, como una familia o una reserva.</p>${button('+ Nuevo grupo','group-new','primary')}</section>`);}
function editGroup(id){const t=trip(),g=t.groups.find(g=>g.id===id)||{id:C.uid(),name:'',color:palette[t.groups.length%palette.length]};modal(id?'Editar grupo':'Nuevo grupo',`<form id="group-form"><div class="form-grid">${field('Nombre','name',g.name,'text','required')}${field('Color en el mapa','color',g.color,'color')}</div><div class="modal-actions">${id?button('Eliminar grupo','group-delete','danger',`data-id="${esc(id)}" style="margin-right:auto"`):''}${button('Cancelar','close')}<button class="primary" type="submit">Guardar grupo</button></div></form>`);$('#group-form').onsubmit=e=>{e.preventDefault();mutate(()=>{const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim()||t.groups.some(q=>q.id!==g.id&&C.norm(q.name)===C.norm(f.name)))throw Error('Elegí un nombre de grupo único.');Object.assign(g,{name:f.name.trim(),color:f.color});if(!id)t.groups.push(g);closeModal();});};}
function board(id){const t=trip(),p=t.passengers.find(p=>p.id===id);if(!p.groupId){mutate(()=>C.setBoarded(t,id,!p.boarded,false));return;}modal(p.boarded?'Desmarcar embarque':'Confirmar embarque',`<p>${esc(fullName(p))} pertenece a <strong>${esc(group(t,p.groupId)?.name)}</strong>.</p><div class="modal-actions">${button('Cancelar','close')}${button('Solo esta persona','board-one')}${button('Todo el grupo','board-all','primary')}</div>`);for(const [action,whole]of [['board-one',false],['board-all',true]])$(`[data-action=${action}]`).onclick=()=>mutate(()=>{C.setBoarded(t,id,!p.boarded,whole);closeModal();});}
function roomTable(t,people){return reportTable(['Grupo','Pasajero','Documento','Nacimiento','Edad','Régimen','Habitación','Camas','N.º'],people.map(p=>[group(t,p.groupId)?.name||'—',fullName(p),p.document,dateText(p.birthDate),C.age(p.birthDate,t.departure),p.meal,p.roomType,p.beds,p.room]));}
function renderRooming(t){const hotels=[...new Set(t.passengers.map(p=>p.hotel).filter(Boolean))].sort();$('#main').innerHTML=pageTitle('ALOJAMIENTOS','Rooming','La distribución se actualiza desde las fichas de pasajeros.',button('Preparar PDF','rooming-report','primary'))+(hotels.length?hotels.map(h=>{const people=t.passengers.filter(p=>p.hotel===h).sort((a,b)=>(a.groupId+a.room).localeCompare(b.groupId+b.room));return `<section class="card room-card"><div class="card-header"><div><h2>${esc(h)}</h2><small>${dateText(t.checkIn)} → ${dateText(t.checkOut)} · ${people.length} huéspedes</small></div><span class="chip">${new Set(people.map(p=>p.room).filter(Boolean)).size} habitaciones numeradas</span></div>${roomTable(t,people)}</section>`;}).join(''):'<section class="card empty"><h3>Todavía no hay alojamientos asignados</h3><p>Completá el hospedaje, habitación y régimen en la ficha de cada pasajero. Podés aplicarlos a todo su grupo.</p></section>');}
const reportNames={passengers:'Lista de pasajeros',rooming:'Rooming por alojamiento',vouchers:'Vouchers por grupo',manifest:'Manifiesto de viaje',insurance:'Datos para el seguro',seating:'Taquilla y butacas'};
function renderDocuments(t){$('#main').innerHTML=pageTitle('DOCUMENTACIÓN','Documentos de la salida','Todos se generan con la información actual del viaje.')+`<div class="documents">${Object.entries(reportNames).map(([id,name])=>`<section class="card"><div class="doc-icon">PDF</div><h2>${name}</h2><p>${{passengers:'Personas, documentos, contacto y punto de embarque.',rooming:'Huéspedes agrupados por hospedaje y reserva.',vouchers:'Un comprobante por grupo con los servicios registrados.',manifest:'Datos del transporte, tripulación y pasajeros.',insurance:'Identificación, nacimiento y nacionalidad.',seating:'Plano de cada piso y pasajeros asignados.'}[id]}</p>${button('Ver y preparar PDF','report','secondary',`data-type="${id}"`)}</section>`).join('')}</div><div class="notice">Se abre una vista de impresión A4. Elegí “Guardar como PDF” en el diálogo de tu navegador. El manifiesto es una plantilla operativa editable mediante los datos del viaje.</div>`;}
function reportTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function reportHeader(t,title){return `<div class="report-header"><small>${esc(t.provider||'CORAL · GESTIÓN DE SALIDAS')}</small><h1>${esc(title)}</h1><h2>${esc(t.name)}</h2><div class="report-meta"><p>${esc(t.origin)} → ${esc(t.destination)}</p><p>Salida: ${dateText(t.departure)}<br>Regreso: ${dateText(t.returnDate)}</p><p>Check in: ${dateText(t.checkIn)}<br>Check out: ${dateText(t.checkOut)}</p></div></div>`;}
function reportHTML(t,type,filter=''){let people=t.passengers;const head=reportHeader(t,reportNames[type]);if(type==='passengers')return head+reportTable(['Butaca','Grupo','Nombre y apellido','Documento','Destino','Embarque','Teléfono'],people.map(p=>[p.noSeat?'Sin butaca':seatLabel(t,p.seatId),group(t,p.groupId)?.name||'—',fullName(p),p.document,p.destination,p.boarding,p.phone]));if(type==='insurance')return head+reportTable(['Nombre','Apellido','Nacimiento','Sexo','Tipo doc.','Documento','Nacionalidad'],people.map(p=>[p.firstName,p.lastName,dateText(p.birthDate),p.sex,p.documentType,p.document,p.nationality]));if(type==='manifest')return head+`<div class="report-meta"><p>Empresa: ${esc(t.carrier)}<br>Unidad: ${esc(t.vehicle)} · Dominio: ${esc(t.plate)}</p><p>Paso fronterizo: ${esc(t.border)}<br>Ruta: ${esc(t.route)}</p></div>`+reportTable(['Tipo','Nombre y apellido','Documento','Nacionalidad','Ocupación','Sexo','Nacimiento','Residencia'],[...people].sort((a,b)=>a.role.localeCompare(b.role)).map(p=>[p.role,fullName(p),p.documentType+' '+p.document,p.nationality,p.occupation,p.sex,dateText(p.birthDate),p.residence]));if(type==='rooming'){const hotels=[...new Set(people.map(p=>p.hotel).filter(Boolean))].sort().filter(h=>!filter||h===filter);return hotels.length?hotels.map(h=>`<section class="report-section">${reportHeader(t,'Rooming · '+h)}${roomTable(t,people.filter(p=>p.hotel===h).sort((a,b)=>(a.groupId+a.room).localeCompare(b.groupId+b.room)))}</section>`).join(''):head+'<p>No hay alojamientos asignados.</p>';}
if(type==='vouchers'){const groups=t.groups.filter(g=>!filter||g.id===filter);return groups.length?groups.map(g=>{const ps=people.filter(p=>p.groupId===g.id);return `<section class="report-section">${reportHeader(t,'Voucher · '+g.name)}<p><strong>Reserva:</strong> ${esc(g.name)} · ${ps.length} personas</p>${reportTable(['Pasajero','Documento','Butaca'],ps.map(p=>[fullName(p),p.document,p.noSeat?'Sin butaca':seatLabel(t,p.seatId)]))}<h3 style="margin-top:25px">Servicios registrados</h3>${reportTable(['Pasajero','Hospedaje','Habitación','Régimen'],ps.map(p=>[fullName(p),p.hotel,p.roomType+(p.room?' · '+p.room:''),p.meal]))}<p><strong>Presentación:</strong> ${esc(t.presentation)} · ${esc(t.boardingPlace)}</p><p><strong>Coordinación:</strong> ${esc(t.coordinator)}</p>${ps.filter(p=>p.notes).map(p=>`<p>${esc(fullName(p))}: ${esc(p.notes)}</p>`).join('')}</section>`;}).join(''):head+'<p>No hay grupos creados.</p>';}
if(type==='seating')return t.floors.map(f=>`<section class="report-section">${reportHeader(t,'Taquilla · '+f.name)}<div class="print-seat-map" style="grid-template-columns:repeat(${f.cols},1fr)">${Array.from({length:f.rows*f.cols},(_,i)=>{const s=f.seats.find(s=>s.row===Math.floor(i/f.cols)&&s.col===i%f.cols),p=s&&people.find(p=>p.seatId===s.id);const fixture=(f.fixtures||[]).find(x=>x.row===Math.floor(i/f.cols)&&x.col===i%f.cols);return s?`<span><b>${esc(s.label)}</b>${p?esc(fullName(p)):'Libre'}</span>`:fixture?`<span class="print-fixture">${C.fixtureTypes[fixture.type]}</span>`:'<span class="blank"></span>';}).join('')}</div></section>`).join('');return '';}
function showReport(type,filter=''){reportType=type;reportFilter=filter;const t=trip();let opts=[];if(type==='rooming')opts=[...new Set(t.passengers.map(p=>p.hotel).filter(Boolean))].map(h=>[h,h]);if(type==='vouchers')opts=t.groups.map(g=>[g.id,g.name]);const missing=t.passengers.filter(p=>!p.document).length;$('#main').innerHTML=pageTitle('VISTA PREVIA',reportNames[type],`${t.passengers.length} personas · ${t.name}`,button('Volver','goto-documents')+button('Imprimir / Guardar PDF','print','primary'))+((type==='rooming'||type==='vouchers')?`<div class="report-select">${selectField(type==='rooming'?'Alojamiento':'Grupo','reportFilter',[['','Todos'],...opts],filter)}</div>`:'')+(missing?`<div class="notice warning">Hay ${missing} personas sin documento. Revisá los datos antes de entregar el archivo.</div>`:'')+(type==='rooming'&&t.passengers.some(p=>!p.hotel)?'<div class="notice warning">Los pasajeros sin hospedaje asignado no aparecen en el rooming.</div>':'')+(type==='vouchers'&&t.passengers.some(p=>!p.groupId)?'<div class="notice warning">Los pasajeros sin grupo no tienen voucher. Asignales un grupo para incluirlos.</div>':'')+`<div class="report-preview">${reportHTML(t,type,filter)}</div>`;const select=$('[name=reportFilter]');if(select)select.onchange=e=>showReport(type,e.target.value);}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download(`coral-respaldo-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2),'application/json');}
function exportCSV(){const t=trip(),fields=[['firstName','Nombre'],['lastName','Apellido'],['documentType','Tipo documento'],['document','Documento'],['birthDate','Nacimiento'],['nationality','Nacionalidad'],['phone','Teléfono'],['hotel','Hospedaje'],['roomType','Habitación'],['room','Número habitación'],['meal','Régimen'],['boarding','Embarque'],['notes','Observaciones']];const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Grupo','Butaca',...fields.map(f=>f[1])],...t.passengers.map(p=>[group(t,p.groupId)?.name||'',p.noSeat?'Sin butaca':seatLabel(t,p.seatId),...fields.map(([k])=>p[k])])];download('pasajeros.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function demo(){mutate(()=>{const t=C.blankTrip();t.name='Demo · Costa de Brasil';t.departure='2027-01-15';t.returnDate='2027-01-24';t.checkIn='2027-01-17';t.checkOut='2027-01-23';t.configured=true;t.floors=C.layout(58,'double','2-2');t.boardingPlace='Terminal de Córdoba';t.groups=[{id:C.uid(),name:'Familia del Mar',color:palette[0]},{id:C.uid(),name:'Amigos del Sur',color:palette[1]}];[['Ana','Ejemplo'],['Pedro','Ejemplo'],['Lucía','Prueba'],['Martín','Prueba']].forEach(([firstName,lastName],i)=>{t.passengers.push({...C.blankPassenger(),firstName,lastName,document:`DEMO-00${i+1}`,birthDate:'1990-06-15',groupId:t.groups[i<2?0:1].id,seatId:C.seats(t)[i].id,hotel:'Posada de ejemplo',roomType:'Doble',room:i<2?'101':'102',meal:'Desayuno',origin:t.origin,destination:t.destination,boarding:t.boardingPlace,boarded:i<2});});data.trips.push(t);activeId=t.id;view='overview';});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-view]');if(!b||b.disabled)return;if(b.dataset.view==='boarding'){location.href='embarque.html?salida='+encodeURIComponent(activeId);return;}if(b.dataset.view){view=b.dataset.view;query='';moving='';render();return;}const a=b.dataset.action,id=b.dataset.id,t=trip();if(a==='close'){closeModal();return;}if(a==='new'){newTrip();return;}if(a==='restore'){$('#restore-file').click();return;}if(a==='backup'){backup();return;}if(a==='demo'){demo();return;}if(storageBlocked){notify('Restaurá un respaldo para continuar.');return;}switch(a){case'goto-bus':view='bus';render();break;case'goto-documents':view='documents';render();break;case'trip-edit':editTrip();break;case'open-trip':activeId=id;view='overview';floorIndex=0;render();break;case'clone-trip':{const src=data.trips.find(s=>s.id===id);promptValue('Reutilizar plano','Nombre de la nueva salida',src.name+' · Nueva salida',name=>{const nt=C.blankTrip();nt.name=name;nt.origin=src.origin;nt.destination=src.destination;nt.floors=structuredClone(src.floors);nt.floors.forEach(f=>{f.id=C.uid();f.seats.forEach(s=>s.id=C.uid());(f.fixtures||[]).forEach(s=>s.id=C.uid());});data.trips.push(nt);activeId=nt.id;floorIndex=0;view='bus';});break;}case'floor':floorIndex=Number(b.dataset.index);render();break;case'tool':tool=b.dataset.tool;moving='';render();break;case'seat':handleSeat(id);break;case'fixture':handleFixture(id);break;case'space':handleSpace(Number(b.dataset.row),Number(b.dataset.col));break;case'add-row':mutate(()=>{if(t.floors[floorIndex].rows>=40)throw Error('Máximo 40 filas por piso.');t.floors[floorIndex].rows++;});break;case'remove-row':mutate(()=>{const f=t.floors[floorIndex];if(f.rows<=1||[...f.seats,...(f.fixtures||[])].some(s=>s.row===f.rows-1))throw Error('La última fila debe estar vacía.');f.rows--;});break;case'floor-name':promptValue('Nombre del piso','Nombre',t.floors[floorIndex].name,name=>{if(!name)throw Error('Completá el nombre.');t.floors[floorIndex].name=name;});break;case'confirm-layout':mutate(()=>{C.validateTrip(t);t.configured=true;moving='';});break;case'unlock-layout':mutate(()=>{t.configured=false;tool='add';moving='';});break;case'passenger-new':editPassenger();break;case'passenger-seat':editPassenger('',id);break;case'passenger-edit':editPassenger(id);break;case'passenger-delete':confirmAction('Eliminar pasajero','Se eliminará su ficha y se liberará su butaca. Los demás pasajeros se conservarán.',()=>mutate(()=>{t.passengers=t.passengers.filter(p=>p.id!==id);}));break;case'assign-seat':{const free=t.passengers.filter(p=>!p.seatId&&!p.noSeat);if(!free.length){notify('No hay pasajeros pendientes de asignación.');break;}modal('Asignar butaca '+seatLabel(t,id),`<form id="assign-form">${selectField('Pasajero','passenger',free.map(p=>[p.id,fullName(p)]))}<div class="modal-actions">${button('Cancelar','close')}<button class="primary">Asignar</button></div></form>`);$('#assign-form').onsubmit=e=>{e.preventDefault();mutate(()=>{const p=t.passengers.find(p=>p.id===new FormData(e.target).get('passenger'));C.savePassenger(t,{...p,seatId:id});closeModal();});};break;}case'group-new':editGroup();break;case'group-edit':editGroup(id);break;case'group-delete':confirmAction('Eliminar grupo','Los pasajeros se conservarán y quedarán sin grupo.',()=>mutate(()=>{t.groups=t.groups.filter(g=>g.id!==id);t.passengers.forEach(p=>{if(p.groupId===id)p.groupId='';});}));break;case'board':board(id);break;case'group-board':confirmAction('Embarcar grupo','Se marcarán como embarcados todos los integrantes de este grupo.',()=>mutate(()=>{t.passengers.forEach(p=>{if(p.groupId===id)p.boarded=true;});}));break;case'csv':exportCSV();break;case'report':showReport(b.dataset.type);break;case'rooming-report':view='documents';render();showReport('rooming');break;case'print':$('#print-area').innerHTML=reportHTML(t,reportType,reportFilter);document.title=reportNames[reportType]+' - '+t.name;window.print();document.title='Coral · Salidas';break;}});
$('#new-trip').onclick=newTrip;$('#backup').onclick=backup;$('#restore').onclick=()=>$('#restore-file').click();$('#trip-select').onchange=e=>{activeId=e.target.value;floorIndex=0;moving='';view='overview';render();};
$('#restore-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('El archivo supera el límite de 10 MB.');const incoming=C.validateStore(JSON.parse(await file.text()));confirmAction('Restaurar respaldo',`Se cargarán ${incoming.trips.length} salidas y se reemplazará el guardado actual. Descargá un respaldo antes si necesitás conservarlo.`,()=>mutate(()=>{data=incoming;activeId=data.trips[0]?.id||'';floorIndex=0;view='overview';}));}catch(err){notify('No se pudo importar: '+err.message);}};
window.addEventListener('coral-cloud-update',()=>{if(saving)return;if($('#modal').open){remotePending=true;notify('Hay cambios nuevos en otro equipo. Cerrá este formulario para cargarlos.');return;}cloudBase=CoralCloud.snapshot();data=structuredClone(cloudBase.data);if(!data.trips.some(t=>t.id===activeId))activeId=data.trips[0]?.id||'';render();$('#save-status').textContent='Sincronizado con Firebase';});
render();

$('#modal').addEventListener('close',()=>{if(remotePending&&!saving){cloudBase=CoralCloud.snapshot();data=structuredClone(cloudBase.data);remotePending=false;render();}});
try{if(localStorage.getItem(KEY)){
 const migrate=document.createElement('button');migrate.className='secondary full';migrate.textContent='Importar datos de este equipo';$('#backup').before(migrate);
 migrate.onclick=()=>{try{const legacy=C.validateStore(JSON.parse(localStorage.getItem(KEY)));confirmAction('Importar datos locales',`Se guardarán ${legacy.trips.length} salidas de este navegador en Firebase. Si una salida ya existe, se reemplazará. Las demás salidas en la nube se conservarán.`,()=>mutate(()=>{const merged=new Map(data.trips.map(t=>[t.id,t]));legacy.trips.forEach(t=>merged.set(t.id,t));data={version:1,trips:[...merged.values()]};activeId=data.trips[0]?.id||'';}));}catch(e){notify('No se pudo importar: '+e.message);}};
}}catch{}

